CREATE TABLE IF NOT EXISTS master_inbox(message_id TEXT PRIMARY KEY REFERENCES messages(id),conversation_id TEXT NOT NULL REFERENCES conversations(id),state TEXT NOT NULL DEFAULT 'pending',turn_id TEXT,preanalysis TEXT NOT NULL CHECK(json_valid(preanalysis)),created_seq INTEGER NOT NULL UNIQUE);
CREATE TABLE IF NOT EXISTS master_events(sequence INTEGER PRIMARY KEY AUTOINCREMENT,conversation_id TEXT NOT NULL REFERENCES conversations(id),kind TEXT NOT NULL,payload TEXT NOT NULL CHECK(json_valid(payload)),created_at INTEGER NOT NULL DEFAULT(unixepoch()));
CREATE INDEX IF NOT EXISTS master_events_conversation ON master_events(conversation_id,sequence);
CREATE TABLE IF NOT EXISTS master_action_receipts(operation_key TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id),tool_name TEXT NOT NULL,arguments TEXT NOT NULL,state TEXT NOT NULL,result TEXT);
CREATE TABLE IF NOT EXISTS master_client_receipts(client_id TEXT NOT NULL,client_msg_id TEXT NOT NULL,message_id TEXT NOT NULL REFERENCES messages(id),fingerprint TEXT NOT NULL,cursor INTEGER NOT NULL,PRIMARY KEY(client_id,client_msg_id));
CREATE TABLE IF NOT EXISTS master_questions(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id),scope_id TEXT NOT NULL,text TEXT NOT NULL,blocking INTEGER NOT NULL,default_answer TEXT,created_at INTEGER NOT NULL,answer TEXT,reminded_at INTEGER,applied_default INTEGER NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS master_turn_state(conversation_id TEXT NOT NULL REFERENCES conversations(id),scope_id TEXT NOT NULL,messages TEXT NOT NULL CHECK(json_valid(messages)),seen TEXT NOT NULL CHECK(json_valid(seen)),steps INTEGER NOT NULL DEFAULT 0,PRIMARY KEY(conversation_id,scope_id));
CREATE TABLE IF NOT EXISTS master_notices(id TEXT PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id),fingerprint TEXT NOT NULL,message_id TEXT NOT NULL REFERENCES messages(id),event_sequence INTEGER NOT NULL REFERENCES master_events(sequence));
CREATE INDEX IF NOT EXISTS master_inbox_conversation_state ON master_inbox(conversation_id,state,created_seq);
